179	            float inv_sum = (sum == 0.f || sum != sum) ? 1.f : 1.f / sum;
180	            lse(mi) = (sum == 0.f || sum != sum) ? (Split ? -INFINITY : INFINITY) : row_max(mi) * softmax_scale + __logf(sum);
