static int nfail = 0;
#define CHECK(cond, msg) do { if (!(cond)) { printf("FAIL %s (lane %d): %s\n", msg, lane, __func__); nfail++; } } while(0)

// ---------------------------------------------------------------------------
// Test 1: mma.m16n8k16 with explicit fragments.
// A[m][k] = m*16 + k (bf16), B[k][n] = k*8 + n (bf16).
// D[m][n] = sum_k A[m][k]*B[k][n].
// A fragment: lane l, g=l/4, t=l%4:
//   a0=(g,2t), a1=(g+8,2t), a2=(g,2t+8), a3=(g+8,2t+8)  [each = 2 packed bf16]
// B fragment: b0=(2t,g),(2t+1,g); b1=(2t+8,g),(2t+9,g)
// D fragment: d0=(g,2t), d1=(g,2t+1), d2=(g+8,2t), d3=(g+8,2t+1)
// ---------------------------------------------------------------------------
__global__ void test_mma_explicit(float* got) {
    int lane = threadIdx.x;
    int g = lane >> 2, t = lane & 3;
    uint32_t a[4], b[2];
    __nv_bfloat16 a00 = __float2bfloat16((float)(g * 16 + 2 * t));
    __nv_bfloat16 a01 = __float2bfloat16((float)(g * 16 + 2 * t + 1));
    __nv_bfloat16 a10 = __float2bfloat16((float)((g + 8) * 16 + 2 * t));
    __nv_bfloat16 a11 = __float2bfloat16((float)((g + 8) * 16 + 2 * t + 1));
    __nv_bfloat16 a20 = __float2bfloat16((float)(g * 16 + 2 * t + 8));
    __nv_bfloat16 a21 = __float2bfloat16((float)(g * 16 + 2 * t + 9));
    __nv_bfloat16 a30 = __float2bfloat16((float)((g + 8) * 16 + 2 * t + 8));
    __nv_bfloat16 a31 = __float2bfloat16((float)((g + 8) * 16 + 2 * t + 9));
    a[0] = pack2(a00, a01); a[1] = pack2(a10, a11);
    a[2] = pack2(a20, a21); a[3] = pack2(a30, a31);
    __nv_bfloat16 b00 = __float2bfloat16((float)((2 * t) * 8 + g));
    __nv_bfloat16 b01 = __float2bfloat16((float)((2 * t + 1) * 8 + g));
    __nv_bfloat16 b10 = __float2bfloat16((float)((2 * t + 8) * 8 + g));
    __nv_bfloat16 b11 = __float2bfloat16((float)((2 * t + 9) * 8 + g));
    b[0] = pack2(b00, b01); b[1] = pack2(b10, b11);
    float c[4] = {0, 0, 0, 0}, d[4];
    mma_bf16(d, a, b, c);
    // expected D[m][n] = sum_k (m*16+k)(k*8+n) over bf16-rounded operands.
    // Verify d0 = D[g][2t], d1 = D[g][2t+1], d2 = D[g+8][2t], d3 = D[g+8][2t+1]
    float exp[4][2] = {{(float)g, 2 * t}, {(float)g, 2 * t + 1},
                       {(float)g + 8, 2 * t}, {(float)g + 8, 2 * t + 1}};
    float ref[4];
    for (int i = 0; i < 4; ++i) {
        int m = (int)exp[i][0], n = (int)exp[i][1];
        float s = 0.f;
        for (int k = 0; k < 16; ++k) {
            float av = __bfloat162float(__float2bfloat16((float)(m * 16 + k)));
            float bv = __bfloat162float(__float2bfloat16((float)(k * 8 + n)));
            s += av * bv;
        }
        ref[i] = s;
    }
    float tol = 0.05f * (1.f + fabsf(ref[0]));
    CHECK(fabsf(d[0] - ref[0]) < tol, "mma d0");
    CHECK(fabsf(d[1] - ref[1]) < tol, "mma d1");
    CHECK(fabsf(d[2] - ref[2]) < tol, "mma d2");
    CHECK(fabsf(d[3] - ref[3]) < tol, "mma d3");
    for (int i = 0; i < 4; ++i) got[i * 32 + lane] = d[i];
}

// ---------------------------------------------------------------------------
// Test 2: ldmatrix.x4 (non-trans) from 16x16 row-major tile T[r][c] = r*16+c.
// Expect: r0 = T[g][2t..2t+1], r1 = T[g+8][2t..], r2 = T[g][2t+8..], r3 = T[g+8][2t+8..]
// ---------------------------------------------------------------------------
__global__ void test_ldsm_x4(float* got) {
    __shared__ __align__(16) __nv_bfloat16 tile[16][16];
    int lane = threadIdx.x;
    for (int i = lane; i < 16 * 16; i += 32) {
        int r = i / 16, c = i % 16;
        tile[r][c] = __float2bfloat16((float)(r * 16 + c));
    }
    __syncthreads();
    int g = lane >> 2, t = lane & 3;
    // address: matrix m = lane/8 -> byte 128*m; row within matrix = lane%8
    int row = (lane % 8) + 8 * ((lane / 8) & 1);
    int col = 8 * ((lane / 8) >> 1);
    uint32_t r[4];
    ldmatrix_x4(r, &tile[row][col]);
    int exp[4][2] = {{g, 2 * t}, {g + 8, 2 * t}, {g, 2 * t + 8}, {g + 8, 2 * t + 8}};
    for (int i = 0; i < 4; ++i) {
        float v0 = bf2f(r[i], 0), v1 = bf2f(r[i], 1);
        CHECK(fabsf(v0 - (float)(exp[i][0] * 16 + exp[i][1])) < 0.5f, "ldsm_x4 lo");
        CHECK(fabsf(v1 - (float)(exp[i][0] * 16 + exp[i][1] + 1)) < 0.5f, "ldsm_x4 hi");
    }
    for (int i = 0; i < 4; ++i) { got[(2 * i) * 32 + lane] = bf2f(r[i], 0); got[(2 * i + 1) * 32 + lane] = bf2f(r[i], 1); }
}

// ---------------------------------------------------------------------------
// Test 3: ldmatrix.x4.trans from 16x16 row-major tile T[r][c] = r*16+c.
// Expect (transposed 8x8 matrices): r0 = T[2t][g], r1 = T[2t+8][g],
//   r2 = T[2t][g+8], r3 = T[2t+8][g+8]
// ---------------------------------------------------------------------------
__global__ void test_ldsm_x4_trans(float* got) {
    __shared__ __align__(16) __nv_bfloat16 tile[16][16];
    int lane = threadIdx.x;
    for (int i = lane; i < 16 * 16; i += 32) {
        int r = i / 16, c = i % 16;
        tile[r][c] = __float2bfloat16((float)(r * 16 + c));
    }
    __syncthreads();
    int g = lane >> 2, t = lane & 3;
    int row = (lane % 8) + 8 * ((lane / 8) & 1);
    int col = 8 * ((lane / 8) >> 1);
    uint32_t r[4];
    ldmatrix_x4_trans(r, &tile[row][col]);
    int exp[4][2] = {{2 * t, g}, {2 * t + 8, g}, {2 * t, g + 8}, {2 * t + 8, g + 8}};
    for (int i = 0; i < 4; ++i) {
        float v0 = bf2f(r[i], 0), v1 = bf2f(r[i], 1);
        CHECK(fabsf(v0 - (float)(exp[i][0] * 16 + exp[i][1])) < 0.5f, "ldsm_x4t lo");
        CHECK(fabsf(v1 - (float)(exp[i][0] * 16 + exp[i][1] + 1)) < 0.5f, "ldsm_x4t hi");
    }
    for (int i = 0; i < 4; ++i) { got[(2 * i) * 32 + lane] = bf2f(r[i], 0); got[(2 * i + 1) * 32 + lane] = bf2f(r[i], 1); }
}

// ---------------------------------------------------------------------------
// Test 4: full S = Q(16x16) * K^T(16x16 -> 16x8) pipeline:
//   Q stored as q[16][16] (row-major), K stored as k[16][16] (row-major k[n][d]).
//   S[m][n] = sum_d q[m][d] * k[n][d]  for n = 0..7.
//   A = ldmatrix.x4(q + 0,0)          (Q fragment)
//   B from k[n][d]: need B[k=d][n] = k[n][d] -> element k[g][2t] for b0.
//   Try A: B = {r0, r2} of non-trans x4 from k tile (B[2t][g] = k[g][2t]).
//   Try B: B = ldmatrix.x4.trans (B[2t][g] = k[2t][g]) -- expected WRONG, to confirm.
// ---------------------------------------------------------------------------
__global__ void test_s_pipeline(float* got, int mode) {
    __shared__ __align__(16) __nv_bfloat16 q[16][16];
    __shared__ __align__(16) __nv_bfloat16 k[16][16];
    int lane = threadIdx.x;
    for (int i = lane; i < 16 * 16; i += 32) {
        int r = i / 16, c = i % 16;
        q[r][c] = __float2bfloat16((float)(r * 16 + c + 1));      // arbitrary values
        k[r][c] = __float2bfloat16((float)(r * 7 + c * 3 + 2));
    }
    __syncthreads();
    int g = lane >> 2, t = lane & 3;
    int row = (lane % 8) + 8 * ((lane / 8) & 1);
    int col = 8 * ((lane / 8) >> 1);
    uint32_t a[4], b[2];
    ldmatrix_x4(a, &q[row][col]);
    if (mode == 0) {
        // B = {r0, r2} of non-trans x4 from k[0][0]  (b0 = k[g][2t], b1 = k[g][2t+8])
        uint32_t r[4];
        ldmatrix_x4(r, &k[row][col]);
        b[0] = r[0]; b[1] = r[2];
    } else {
        // B = ldmatrix.x4.trans  (b0 = k[2t][g], b1 = k[2t+8][g])
        uint32_t r[4];
        ldmatrix_x4_trans(r, &k[row][col]);
        b[0] = r[0]; b[1] = r[2];
    }
    float c[4] = {0, 0, 0, 0}, d[4];
    mma_bf16(d, a, b, c);
    // reference S[m][n] = sum_d q[m][d] * k[n][d] for m = g, g+8; n = 2t, 2t+1
    float ref[4];
    int ms[4] = {g, g, g + 8, g + 8}, ns[4] = {2 * t, 2 * t + 1, 2 * t, 2 * t + 1};
    for (int i = 0; i < 4; ++i) {
        float s = 0.f;
        for (int dd = 0; dd < 16; ++dd) {
            float qv = __bfloat162float(q[ms[i]][dd]);
            float kv = __bfloat162float(k[ns[i]][dd]);
            s += qv * kv;
        }
        ref[i] = s;
    }
    float tol = 0.05f * (1.f + fabsf(ref[0]));
    CHECK(fabsf(d[0] - ref[0]) < tol, "S d0");
    CHECK(fabsf(d[1] - ref[1]) < tol, "S d1");
    CHECK(fabsf(d[2] - ref[2]) < tol, "S d2");
    CHECK(fabsf(d[3] - ref[3]) < tol, "S d3");
    for (int i = 0; i < 4; ++i) got[i * 32 + lane] = d[i];
}

int main() {
    float* dgot;
    CUDA_CHECK(cudaMalloc(&dgot, 128 * sizeof(float)));
    float* hgot = (float*)malloc(128 * sizeof(float));
    int fails_total = 0;

    auto run = [&](const char* name, void (*k)(float*), int mode = 0) {
        nfail = 0;
        k<<<1, 32>>>(dgot);
        CUDA_CHECK(cudaDeviceSynchronize());
        printf("%s: %s (%d fails)\n", name, nfail == 0 ? "PASS" : "FAIL", nfail);
        fails_total += nfail;
    };
    run("mma explicit fragments", test_mma_explicit);
    run("ldmatrix.x4", test_ldsm_x4);
    run("ldmatrix.x4.trans", test_ldsm_x4_trans);
    // mode 0: B = {r0,r2} non-trans (hypothesis: correct). mode 1: trans (hypothesis: wrong)
    run("S pipeline mode0 (B={r0,r2} non-trans)", test_s_pipeline, 0);
    run("S pipeline mode1 (B from x4.trans)", test_s_pipeline, 1);

    printf("TOTAL FAILS: %d\n", fails_total);
    return fails_total ? 1 : 0;
}

