// A[m][k] = m*16 + k (bf16), B[k][n] = k*8 + n (bf16).
// D[m][n] = sum_k A[m][k]*B[k][n].
// A fragment: lane l, g=l/4, t=l%4:
//   a0=(g,2t), a1=(g+8,2t), a2=(g,2t+8), a3=(g+8,2t+8)  [each = 2 packed bf16]
