// D fragment: d0=(g,2t), d1=(g,2t+1), d2=(g+8,2t), d3=(g+8,2t+1)
// ---------------------------------------------------------------------------
__global__ void test_mma_explicit(float* got) {
    int lane = threadIdx.x;
