    run("ldmatrix.x4", test_ldsm_x4);
    run("ldmatrix.x4.trans", test_ldsm_x4_trans);
    // mode 0: B = {r0,r2} non-trans (hypothesis: correct). mode 1: trans (hypothesis: wrong)
    run("S pipeline mode0 (B={r0,r2} non-trans)", test_s_pipeline, 0);
    run("S pipeline mode1 (B from x4.trans)", test_s_pipeline, 1);

    printf("TOTAL FAILS: %d\n", fails_total);
    return fails_total ? 1 : 0;
}

